WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL
AND r.biz_code = #{bizCode}
AND r.namespace_id = #{namespaceId}
AND r.env_code = #{envCode}
AND r.app_code = #{appCode}
