SELECT 
FROM ddc_ai_resource
WHERE tenant_id = #{tenantId} AND biz_code = #{bizCode} AND namespace_id = #{namespaceId}
  AND env_code = #{envCode} AND app_code = #{appCode} AND kind = #{kind}
  AND resource_key = #{resourceKey} AND deleted_at IS NULL
